float sdCircle( in vec2 p, in float r ) //this makes a circle
{
    return length(p)-r;
}
float opCutout(float d, float r) //this carves a circle into the other circle
{
    return abs(d + r * 0.5) - r * 0.75; //changes thickness of circle 
}

void mainImage( out vec4 fragColor, in vec2 fragCoord ) //this makes the image work
{

    vec2 uv0 = fragCoord / iResolution.xy;
    vec2 uv = uv0 * 2.0 - 1.0;
    uv.x *= (iResolution.x / iResolution.y);
    uv0.x *= (iResolution.x / iResolution.y)* 0.5; //changes where the screen is i think?

	float c = sdCircle(uv,0.65); //circle reference
    c = opCutout(c+sin(iTime)*0.3, 0.15); //cutout reference 
    c = 1.0 - step(0.0, c); 


    vec3 rgb = vec3(1.0) * c;
    vec4 flipped = vec4(uv0.yx, 1.0, 1.0) * (1.0 - c);
    fragColor = vec4(uv0.xy, 1.0, 1.0) * (c) + flipped; //this always goes last

}
